"use strict";(self.webpackChunkmy_website=self.webpackChunkmy_website||[]).push([[4647],{12208:(e,n,r)=>{r.r(n),r.d(n,{assets:()=>d,contentTitle:()=>i,default:()=>c,frontMatter:()=>o,metadata:()=>t,toc:()=>p});const t=JSON.parse('{"id":"LLM/sft","title":"SFT\u5fae\u8c03qwen2-vl-2b\u6a21\u578b","description":"TRL\u5173\u952e\u53c2\u6570","source":"@site/docs/LLM/4-sft.md","sourceDirName":"LLM","slug":"/LLM/sft","permalink":"/docs/LLM/sft","draft":false,"unlisted":false,"editUrl":"https://github.com/facebook/docusaurus/tree/main/packages/create-docusaurus/templates/shared/docs/LLM/4-sft.md","tags":[],"version":"current","sidebarPosition":4,"frontMatter":{"sidebar_position":4},"sidebar":"tutorialSidebar","previous":{"title":"\u76ee\u524d\u7814\u7a76","permalink":"/docs/LLM/llm"},"next":{"title":"Mamba","permalink":"/docs/LLM/mamba"}}');var a=r(74848),s=r(28453);const o={sidebar_position:4},i="SFT\u5fae\u8c03qwen2-vl-2b\u6a21\u578b",d={},p=[{value:"TRL\u5173\u952e\u53c2\u6570",id:"trl\u5173\u952e\u53c2\u6570",level:2},{value:"\u4ee3\u7801",id:"\u4ee3\u7801",level:2}];function l(e){const n={admonition:"admonition",code:"code",h1:"h1",h2:"h2",header:"header",p:"p",pre:"pre",...(0,s.R)(),...e.components};return(0,a.jsxs)(a.Fragment,{children:[(0,a.jsx)(n.header,{children:(0,a.jsx)(n.h1,{id:"sft\u5fae\u8c03qwen2-vl-2b\u6a21\u578b",children:"SFT\u5fae\u8c03qwen2-vl-2b\u6a21\u578b"})}),"\n",(0,a.jsx)(n.h2,{id:"trl\u5173\u952e\u53c2\u6570",children:"TRL\u5173\u952e\u53c2\u6570"}),"\n",(0,a.jsx)(n.pre,{children:(0,a.jsx)(n.code,{className:"language-bash",children:"per_device_train_batch_size 1\r\ngradient_accumulation_steps 1 \n"})}),"\n",(0,a.jsx)(n.p,{children:"\u6a21\u578b\u6700\u7ec8\u7684batch_size=GPU number * per_device_train_batch_size * gradient_accumulation_steps"}),"\n",(0,a.jsx)(n.pre,{children:(0,a.jsx)(n.code,{className:"language-bash",children:"gradient_checkpointing True\n"})}),"\n",(0,a.jsx)(n.p,{children:"\u5f00\u542f\u68af\u5ea6\u68c0\u67e5\u70b9\uff0c\u6709\u52a9\u4e8e\u51cf\u5c11\u5927\u91cf\u663e\u5b58\u5360\u7528\uff0c\u539f\u6587\u4ecb\u7ecd\u5982\u4e0b\uff1a"}),"\n",(0,a.jsx)(n.admonition,{type:"info",children:(0,a.jsx)(n.p,{children:"Checkpoint a model or part of the model\r\nCheckpointing works by trading compute for memory. Rather than storing all intermediate activations of the entire computation graph for computing backward, the checkpointed part does not save intermediate activations, and instead recomputes them in backward pass. It can be applied on any part of a model.\r\nSpecifically, in the forward pass, function will run in torch.no_grad() manner, i.e., not storing the intermediate activations. Instead, the forward pass saves the inputs tuple and the function parameter. In the backwards pass, the saved inputs and function is retrieved, and the forward pass is computed on function again, now tracking the intermediate activations, and then the gradients are calculated using these activation values.\r\nThe output of function can contain non-Tensor values and gradient recording is only performed for the Tensor values. Note that if the output consists of nested structures (ex: custom objects, lists, dicts etc.) consisting of Tensors, these Tensors nested in custom structures will not be considered as part of autograd.\r\n\u539f\u6587\u5927\u610f\u5982\u4e0b\uff1a\r\n\u68c0\u67e5\u70b9\u6280\u672f\u901a\u8fc7\u4ee5\u8ba1\u7b97\u91cf\u4e3a\u4ee3\u4ef7\u6765\u8282\u7701\u5185\u5b58\uff0c\u5373\u4e0d\u4fdd\u5b58\u6574\u4e2a\u8ba1\u7b97\u56fe\u7684\u6240\u6709\u4e2d\u95f4\u6fc0\u6d3b\u503c\u4ee5\u8ba1\u7b97\u53cd\u5411\u4f20\u64ad\uff0c\u800c\u662f\u5728\u53cd\u5411\u4f20\u64ad\u65f6\u91cd\u65b0\u8ba1\u7b97\u8fd9\u4e9b\u6fc0\u6d3b\u503c\u3002\u5b83\u53ef\u4ee5\u5e94\u7528\u4e8e\u6a21\u578b\u7684\u4efb\u4f55\u90e8\u5206\u3002\r\n\u5177\u4f53\u800c\u8a00\uff0c\u5728\u524d\u5411\u4f20\u9012\u4e2d\uff0c\u51fd\u6570\u5c06\u4ee5 torch.no_grad() \u7684\u65b9\u5f0f\u8fd0\u884c\uff0c\u5373\u4e0d\u4fdd\u5b58\u4e2d\u95f4\u6fc0\u6d3b\u503c\u3002\u76f8\u53cd\uff0c\u5728\u524d\u5411\u4f20\u9012\u4e2d\uff0c\u5c06\u4fdd\u5b58\u8f93\u5165\u5143\u7ec4\u548c\u51fd\u6570\u53c2\u6570\u3002\u5728\u53cd\u5411\u4f20\u9012\u4e2d\uff0c\u68c0\u7d22\u4fdd\u5b58\u7684\u8f93\u5165\u548c\u51fd\u6570\uff0c\u5e76\u518d\u6b21\u5bf9\u51fd\u6570\u8fdb\u884c\u524d\u5411\u4f20\u9012\uff0c\u73b0\u5728\u8ddf\u8e2a\u4e2d\u95f4\u6fc0\u6d3b\u503c\uff0c\u7136\u540e\u4f7f\u7528\u8fd9\u4e9b\u6fc0\u6d3b\u503c\u8ba1\u7b97\u68af\u5ea6\u3002\r\n\u51fd\u6570\u7684\u8f93\u51fa\u53ef\u4ee5\u5305\u542b\u975e\u5f20\u91cf\u503c\uff0c\u5e76\u4e14\u4ec5\u5bf9\u5f20\u91cf\u503c\u6267\u884c\u68af\u5ea6\u8bb0\u5f55\u3002\u8bf7\u6ce8\u610f\uff0c\u5982\u679c\u8f93\u51fa\u5305\u542b\u5d4c\u5957\u7ed3\u6784\uff08\u4f8b\u5982\uff1a\u81ea\u5b9a\u4e49\u5bf9\u8c61\u3001\u5217\u8868\u3001\u5b57\u5178\u7b49\uff09\uff0c\u5176\u4e2d\u5305\u542b\u5f20\u91cf\u7684\u5d4c\u5957\u7ed3\u6784\u5c06\u4e0d\u88ab\u89c6\u4e3a\u81ea\u52a8\u6c42\u5bfc\u7684\u4e00\u90e8\u5206\u3002"})}),"\n",(0,a.jsx)(n.pre,{children:(0,a.jsx)(n.code,{className:"language-bash",children:"report_to none\n"})}),"\n",(0,a.jsx)(n.p,{children:"\u53ef\u7528\u4e8e\u5173\u95ed wandb"}),"\n",(0,a.jsx)(n.h2,{id:"\u4ee3\u7801",children:"\u4ee3\u7801"}),"\n",(0,a.jsx)(n.p,{children:"\u4e0d\u5f00\u542f4bit\u91cf\u5316\u662f\u56e0\u4e3a\u4e0edeepspeed\u51b2\u7a81"}),"\n",(0,a.jsx)(n.p,{children:"\u6ca1\u6709\u4f7f\u7528map\u51fd\u6570\u5904\u7406\u6570\u636e\u96c6\u662f\u56e0\u4e3a\u4f7f\u7528map\u51fd\u6570\u540e\u6bcf\u4e00\u4e2a\u5bf9\u8bdd\u7684content\u90fd\u4f1a\u5b58\u5728video\u9879\uff0c\u800c\u6709\u4e9bvideo\u9879\u4e3anone\uff0c\u8fd9\u4f1a\u4f7f\u5f97\u5728\u8c03\u7528apply_chat_template\u65f6\u5b58\u5728\u591a\u4e2avideo_pad\u5bfc\u81f4\u95ee\u9898\u3002"}),"\n",(0,a.jsx)(n.p,{children:"\u4ee3\u7801\u5982\u4e0b\uff1a"}),"\n",(0,a.jsx)(n.pre,{children:(0,a.jsx)(n.code,{className:"language-python",children:'import json\r\nimport os\r\nimport random\r\nfrom dataclasses import dataclass, field\r\nfrom typing import Any, Optional\r\nfrom functools import partial\r\n\r\nimport torch\r\nfrom datasets import load_dataset\r\nfrom peft import LoraConfig\r\nfrom qwen_vl_utils import process_vision_info\r\nfrom transformers import AutoModelForImageTextToText, AutoProcessor, BitsAndBytesConfig, Qwen2VLProcessor\r\n\r\nfrom datasets import Dataset, DatasetDict\r\nfrom trl import ModelConfig, ScriptArguments, SFTConfig, SFTTrainer, TrlParser, get_kbit_device_map\r\n\r\n\r\n# Enable logging in a Hugging Face Space\r\nos.environ.setdefault("TRACKIO_SPACE_ID", "trl-trackio")\r\n\r\n@dataclass\r\nclass SFTScriptArguments(ScriptArguments):\r\n    """\r\n    Script arguments for the SFT training script.\r\n    """\r\n    data_path: Optional[str] = field(\r\n        default=None,\r\n        metadata={"help": "json file path"},\r\n    )\r\n    jsonl_path: Optional[str] = field(\r\n        default=None,\r\n        metadata={"help": "json file path"},\r\n    )\r\n\r\ndef prepare_dataset(example: dict[str, Any], root_dir: str) -> dict[str, list[dict[str, Any]]]:\r\n    """Prepare dataset example for training."""\r\n    system_message = "You are acting as the grounder now."\r\n    base_prompt = """Given a video and a text query {query}, your goal is to temporally localize the video moment described by the query and \r\n    output the reasoning process and the answer. The reasoning process and answer are enclosed within <think> </think> and <answer> </answer> tags, respectively, i.e.,\r\n    <think> reasoning process here </think><answer> answer here </answer>\r\n    """\r\n    messages = [\r\n        {"role": "system", "content": [{"type": "text", "text": system_message}]},\r\n        {\r\n            "role": "user",\r\n            "content": [\r\n                {\r\n                    "type": "video", \r\n                    "video": os.path.join(root_dir, example[\'video\']), \r\n                    \'min_pixels\': 16 * 28 * 28,\r\n                    \'max_pixels\': 32 * 28 * 28,\r\n                    \'fps\': 1.0 \r\n                },\r\n                {"type": "text", "text": base_prompt.format(query=example[\'problem\'])},\r\n            ],\r\n        },\r\n        {"role": "assistant", "content": [{"type": "text", "text": example["think"] + example["solution"]}]},\r\n    ]\r\n    return {"messages": messages}\r\n\r\n\r\ndef collate_fn(examples: list[dict[str, Any]]) -> dict[str, torch.Tensor]:\r\n    """Collate batch of examples for training."""\r\n    texts = []\r\n    video_inputs = []\r\n\r\n    for i, example in enumerate(examples):\r\n        try:\r\n            video_path = next(\r\n                content["video"]\r\n                for message in example["messages"]\r\n                for content in message["content"]\r\n                if content.get("type") == "video"\r\n            )\r\n            print(f"Processing video: {video_path}")\r\n            messages = [\r\n                {\r\n                    "role": "user",\r\n                    "content": [\r\n                        {\r\n                            "type": "video",\r\n                            "video": video_path,\r\n                            # "total_pixels": 3584 * 28 * 28,\r\n                            \'min_pixels\': 16 * 28 * 28,\r\n                            \'max_pixels\': 32 * 28 * 28,\r\n                            \'fps\': 1.0\r\n                        },\r\n                    ],\r\n                }\r\n            ]\r\n            texts.append(processor.apply_chat_template(example["messages"], tokenize=False))\r\n            video_input = process_vision_info(messages)[1][0]\r\n            video_inputs.append(video_input)\r\n        except Exception as e:\r\n            raise ValueError(f"Failed to process example {i}: {e}") from e\r\n\r\n    inputs = processor(text=texts, videos=video_inputs, return_tensors="pt", padding=True)\r\n\r\n    labels = inputs["input_ids"].clone()\r\n    labels[labels == processor.tokenizer.pad_token_id] = -100\r\n\r\n    # Handle visual tokens based on processor type\r\n    visual_tokens = (\r\n        [151652, 151653, 151656]\r\n        if isinstance(processor, Qwen2VLProcessor)\r\n        else [processor.tokenizer.convert_tokens_to_ids(processor.image_token)]\r\n    )\r\n\r\n    for visual_token_id in visual_tokens:\r\n        labels[labels == visual_token_id] = -100\r\n\r\n    inputs["labels"] = labels\r\n    return inputs\r\n\r\ndef create_dataset_from_jsonl_simple(jsonl_path):\r\n    base_dataset = Dataset.from_json(jsonl_path)\r\n    return DatasetDict({\r\n        "train": base_dataset\r\n    })\r\n\r\nif __name__ == "__main__":\r\n    # Parse arguments\r\n    parser = TrlParser((SFTScriptArguments, SFTConfig, ModelConfig))\r\n    script_args, training_args, model_args = parser.parse_args_and_config()\r\n\r\n    # Configure training args\r\n    training_args.gradient_checkpointing_kwargs = dict(use_reentrant=False)\r\n    training_args.remove_unused_columns = False\r\n\r\n    # Load dataset\r\n    if script_args.jsonl_path:\r\n        # # load dataset from jsonl\r\n        dataset = Dataset.from_json(script_args.jsonl_path)\r\n    else:\r\n        # Load the dataset\r\n        dataset = load_dataset(script_args.dataset_name, name=script_args.dataset_config)\r\n    # trainset, testset = dataset.train_test_split(test_size=0.1).values()\r\n\r\n    # Setup model\r\n    dtype = model_args.dtype if model_args.dtype in ["auto", None] else getattr(torch, model_args.dtype)\r\n\r\n    # Quantization configuration for 4-bit training\r\n    # bnb_config = BitsAndBytesConfig(\r\n    #     load_in_4bit=True,\r\n    #     bnb_4bit_use_double_quant=True,\r\n    #     bnb_4bit_quant_type="nf4",\r\n    #     bnb_4bit_compute_dtype=torch.bfloat16,\r\n    # )\r\n\r\n    # Model initialization\r\n    model_kwargs = dict(\r\n        revision=model_args.model_revision,\r\n        trust_remote_code=model_args.trust_remote_code,\r\n        dtype=dtype,\r\n        attn_implementation=model_args.attn_implementation, \r\n        # device_map=get_kbit_device_map(),\r\n        # quantization_config=bnb_config,\r\n    )\r\n\r\n    model = AutoModelForImageTextToText.from_pretrained(model_args.model_name_or_path, **model_kwargs)\r\n\r\n    peft_config = LoraConfig(\r\n        task_type="CAUSAL_LM",\r\n        r=16,\r\n        lora_alpha=16,\r\n        lora_dropout=0.1,\r\n        bias="none",\r\n        target_modules=[\'q_proj\', \'k_proj\', \'v_proj\', \'o_proj\'], # \'attn.qkv\', \'attn.proj\'\r\n    )\r\n\r\n    # Configure model modules for gradients\r\n    if training_args.gradient_checkpointing:\r\n        model.gradient_checkpointing_enable()\r\n        model.config.use_reentrant = False\r\n        model.enable_input_require_grads()\r\n\r\n    processor = AutoProcessor.from_pretrained(\r\n        model_args.model_name_or_path, trust_remote_code=model_args.trust_remote_code\r\n    )\r\n\r\n        \r\n    # \u4f7f\u7528 map \u51fd\u6570\uff0c\u8ba9 Hugging Face datasets \u5904\u7406\u6570\u636e\u7ba1\u7406\r\n    dataset = [prepare_dataset(example, script_args.data_path) for example in dataset]\r\n    # dataset = dataset.map(\r\n    #     partial(prepare_dataset, root_dir=script_args.data_path),\r\n    #     remove_columns=dataset.column_names,\r\n    #     num_proc=4, # \u53ef\u4ee5\u8bbe\u7f6e\u591a\u8fdb\u7a0b\u52a0\u901f\u5904\u7406\r\n    # )\r\n\r\n    # Initialize trainer\r\n    trainer = SFTTrainer(\r\n        model=model,\r\n        args=training_args,\r\n        train_dataset=dataset,\r\n        data_collator=collate_fn,\r\n        peft_config=peft_config,\r\n        processing_class=processor,\r\n    )\r\n\r\n    # Train model\r\n    trainer.train()\r\n\r\n    # Save final model\r\n    trainer.save_model(training_args.output_dir)\r\n    if training_args.push_to_hub:\r\n        trainer.push_to_hub(dataset_name=script_args.dataset_name)\r\n\r\n    # Cleanup\r\n    del model\r\n    del trainer\r\n    torch.cuda.empty_cache()\n'})})]})}function c(e={}){const{wrapper:n}={...(0,s.R)(),...e.components};return n?(0,a.jsx)(n,{...e,children:(0,a.jsx)(l,{...e})}):l(e)}},28453:(e,n,r)=>{r.d(n,{R:()=>o,x:()=>i});var t=r(96540);const a={},s=t.createContext(a);function o(e){const n=t.useContext(s);return t.useMemo((function(){return"function"==typeof e?e(n):{...n,...e}}),[n,e])}function i(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(a):e.components||a:o(e.components),t.createElement(s.Provider,{value:n},e.children)}}}]);